using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------

var notebook = new Notebook();
var webSearch = new WebSearchTool();

var tools = new AIFunctionFactory[]
{
}.ToList<object>(); // unused – we pass AIFunctions directly

var chatTools = new List<AITool>
{
    AIFunctionFactory.Create(webSearch.Search),
    AIFunctionFactory.Create(notebook.SaveNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// ---------------------------------------------------------------------------
// Chat client with automatic function-calling
// ---------------------------------------------------------------------------

IChatClient client = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = chatTools };

// ---------------------------------------------------------------------------
// System prompt
// ---------------------------------------------------------------------------

const string SystemPrompt = """
    You are a research assistant. The user will give you a topic to research.

    Follow this workflow:
    1. Use the **Search** tool several times with different queries to gather
       information about the topic from the web.
    2. After each search, use **SaveNote** to record the key facts you found,
       including the source URL.
    3. Once you have enough material, call **GetNotes** to review everything
       you collected.
    4. Finally, write a well-structured summary of your research for the user.
       Include source references.

    Be thorough but concise. Aim for 3-5 searches before summarizing.
    """;

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    var history = new List<ChatMessage>
    {
        new(ChatRole.System, SystemPrompt),
        new(ChatRole.User, $"Research this topic: {topic}"),
    };

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\nResearching…\n");
    Console.ResetColor();

    // Clear notebook for each new research session
    notebook.Clear();

    var response = await client.GetResponseAsync(history, chatOptions);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine(response.Text);
    Console.ResetColor();
    Console.WriteLine();
}

