/// <summary>
/// A simple web search tool that fetches results from the web.
/// </summary>
public sealed class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for a query and return a snippet of relevant results.")]
    public async Task<string> Search(
        [Description("The search query string")] string query)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Use DuckDuckGo lite as a simple, key-free search source
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

            var html = await Http.GetStringAsync(url);

            // Extract text snippets from the result page
            var results = ParseSearchResults(html);

            if (results.Count == 0)
                return $"No results found for \"{query}\".";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for \"{query}\":");
            sb.AppendLine();
            foreach (var r in results.Take(5))
            {
                sb.AppendLine($"- [{r.Title}]({r.Url})");
                sb.AppendLine($"  {r.Snippet}");
                sb.AppendLine();
            }
            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseSearchResults(string html)
    {
        var results = new List<SearchResult>();

        // Extract links and snippets from DuckDuckGo Lite HTML
        var linkPattern = new Regex(
            @"<a[^>]+href=""(https?://[^""]+)""[^>]*class=""result-link""[^>]*>(.*?)</a>",
            RegexOptions.IgnoreCase | RegexOptions.Singleline);

        var snippetPattern = new Regex(
            @"<td[^>]*class=""result-snippet""[^>]*>(.*?)</td>",
            RegexOptions.IgnoreCase | RegexOptions.Singleline);

        var links = linkPattern.Matches(html);
        var snippets = snippetPattern.Matches(html);

        for (int i = 0; i < Math.Min(links.Count, 5); i++)
        {
            var title = StripHtml(links[i].Groups[2].Value).Trim();
            var url = links[i].Groups[1].Value.Trim();
            var snippet = i < snippets.Count
                ? StripHtml(snippets[i].Groups[1].Value).Trim()
                : "";

            if (!string.IsNullOrWhiteSpace(title))
                results.Add(new SearchResult(title, url, snippet));
        }

        // Fallback: extract any links if the above patterns didn't match
        if (results.Count == 0)
        {
            var fallback = new Regex(
                @"<a[^>]+href=""(https?://(?!duckduckgo)[^""]+)""[^>]*>(.*?)</a>",
                RegexOptions.IgnoreCase | RegexOptions.Singleline);

            foreach (Match m in fallback.Matches(html).Take(5))
            {
                var title = StripHtml(m.Groups[2].Value).Trim();
                var url = m.Groups[1].Value.Trim();
                if (!string.IsNullOrWhiteSpace(title) && title.Length > 3)
                    results.Add(new SearchResult(title, url, ""));
            }
        }

        return results;
    }

    private static string StripHtml(string html) =>
        Regex.Replace(html, "<[^>]+>", " ").Trim();

    private record SearchResult(string Title, string Url, string Snippet);
}

/// <summary>
/// A note-taking tool that lets the agent save and retrieve research notes.
/// </summary>
public sealed class Notebook
{
    private readonly List<NoteEntry> _notes = [];

    [Description("Save a research note with key facts. Use this after each search to record findings.")]
    public string SaveNote(
        [Description("A concise title for this note")] string title,
        [Description("The content/facts to save")] string content,
        [Description("Source URL where the information was found")] string sourceUrl = "")
    {
        _notes.Add(new NoteEntry(title, content, sourceUrl, DateTime.UtcNow));

        Console.ForegroundColor = ConsoleColor.Magenta;
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        Console.ResetColor();

        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} entries) ===\n");

        for (int i = 0; i < _notes.Count; i++)
        {
            var n = _notes[i];
            sb.AppendLine($"--- Note #{i + 1}: {n.Title} ---");
            sb.AppendLine(n.Content);
            if (!string.IsNullOrWhiteSpace(n.SourceUrl))
                sb.AppendLine($"Source: {n.SourceUrl}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    public void Clear() => _notes.Clear();

    private record NoteEntry(string Title, string Content, string SourceUrl, DateTime SavedAt);
}

